import 'package:flutter/services.dart';

/// Flutter bridge for Alibaba Cloud PNVS graphical authentication (Captcha4).
class OpenElfAliCaptcha {
  const OpenElfAliCaptcha._();

  static const MethodChannel _channel = MethodChannel('openelf_ali_captcha');

  /// Opens the graphical challenge.
  ///
  /// Returns the unmodified JSON proof generated by the Alibaba Cloud client.
  /// A null result means that the user cancelled the challenge.
  static Future<String?> verify({required String captchaId}) {
    if (captchaId.isEmpty) {
      throw ArgumentError.value(captchaId, 'captchaId', 'must not be empty');
    }
    return _channel
        .invokeMethod<String>('verifyCaptcha', {'captchaId': captchaId});
  }
}
